using System;using System.IO;using System.Text;using System.Reflection;using UnityEditor;using UnityEngine;using UnityEngine.UIElements;
namespace ZeroToMillionaire.Editor {
 [InitializeOnLoad] public static class ReviewFixAuditV06 {
 const string Key="ZTM_REVIEW_FIX_V06";static GameView view;static RenderTexture target;static int phase,warm;static double start,at;static bool resetClear;static StringBuilder report=new StringBuilder();
 static string Root=>Directory.GetParent(Application.dataPath).FullName;static string Tag=>SessionState.GetString(Key+"tag","before");static bool Fixed=>Tag=="after";static VisualElement UI=>view.GetComponent<UIDocument>().rootVisualElement;
 static PixelEffects Effects=>(PixelEffects)typeof(GameView).GetField("effects",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(view);
 static ReviewFixAuditV06(){EditorApplication.update+=Tick;}
 public static string Start(string tag){if(EditorApplication.isPlaying)throw new Exception("Own Editor playing");if(tag!="before"&&tag!="after")throw new Exception("Review tag");view=null;phase=warm=0;start=at=0;report.Clear();SessionState.SetString(Key+"tag",tag);Environment.SetEnvironmentVariable("ZTM_QA_SAVE_DIR",Path.Combine(Root,".tooling","review-fixes-v06-"+tag,"save"));UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/Level1.unity");SessionState.SetBool(Key,true);EditorApplication.EnterPlaymode();return "queued "+tag;}
 static void Check(bool ok,string text,bool review=false){report.AppendLine((ok?"PASS":Fixed||!review?"FAIL":"REPRODUCED")+" "+text);if(!ok&&(Fixed||!review))throw new Exception(text);}
 static bool Dialogue=>UI.Q<VisualElement>("heroine-dialogue").resolvedStyle.display==DisplayStyle.Flex;
 static void Capture(string name){var old=RenderTexture.active;RenderTexture.active=target;var t=new Texture2D(360,640,TextureFormat.RGBA32,false);t.ReadPixels(new Rect(0,0,360,640),0,0);t.Apply();File.WriteAllBytes(Path.Combine(Root,"Evidence","review-v06-"+Tag+"-"+name+"-360x640.png"),t.EncodeToPNG());UnityEngine.Object.Destroy(t);RenderTexture.active=old;report.AppendLine("CAPTURE "+name+" frame="+Time.frameCount);}
 static PlayerState FinishFixture(){var s=new PlayerState{cash=500,freeSpins=0};for(int i=0;i<7;i++)s.purchased[i]=true;s.fragments[7]=70;s.tutorial.completed=true;s.tutorial.storySeenMask=7;return s;}
 static void Set(PlayerState s,int page){view.SetQaState(s,page);warm=0;}
 static void Tick(){if(!SessionState.GetBool(Key,false)||!EditorApplication.isPlaying)return;try{if(start==0)start=EditorApplication.timeSinceStartup;if(EditorApplication.timeSinceStartup-start>90)throw new Exception("Review timeout");if(view==null){view=UnityEngine.Object.FindFirstObjectByType<GameView>();if(view==null)return;target=new RenderTexture(360,640,0,RenderTextureFormat.ARGB32);target.Create();view.GetComponent<UIDocument>().panelSettings.targetTexture=target;var s=new PlayerState{cash=100,freeSpins=0};s.fragments[0]=19;s.tutorial.skipped=true;Set(s,0);}
 double now=EditorApplication.timeSinceStartup;++warm;
 if(phase==0&&warm>30){view.QaClick("spin");phase=1;}
 else if(phase==1&&view.QaReelPhase=="match"){var caption=UI.Q<Button>("spin").Q<Label>("button-caption");var status=UI.Q<Label>("quest-status");bool copy=caption.text=="ПРОПУСТИТЬ"&&status.text.Contains("НАГРАДА");Check(copy,"settled phase caption="+caption.text+" status="+status.text,true);var measured=caption.MeasureTextSize(caption.text,0,VisualElement.MeasureMode.Undefined,0,VisualElement.MeasureMode.Undefined);Check(measured.x<=caption.contentRect.width+1,"settled action caption fits");Capture("settled-reward");phase=2;}
 else if(phase==2&&!view.QaSpinning&&UI.Q<VisualElement>("reward-to-task").resolvedStyle.display==DisplayStyle.Flex){Check(view.Model.Snapshot.spins==1&&view.Model.Snapshot.fragments[0]>=20,"real spin created exact pending reward");view.QaClick("menu");view.QaClick("reset");view.QaClick("confirm-reset");resetClear=UI.Q<VisualElement>("reward-to-task").style.display==DisplayStyle.None&&!(bool)typeof(GameView).GetField("rewardPending",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(view);Check(resetClear,"confirmed fast reset clears old reward fly and pending flag",true);Check(view.Model.Snapshot.spins==0&&view.Model.Snapshot.cash==0&&view.Model.Snapshot.freeSpins==3&&view.Model.PurchasedCount==0,"reset changes only authorized fresh-state resources");warm=0;phase=3;}
 else if(phase==3&&warm>3){Capture("fast-reset");Set(FinishFixture(),3);phase=4;}
 else if(phase==4&&warm>30){view.QaClick("buy-7");Check(view.Model.Complete&&view.Model.Snapshot.cash==145,"final manual purchase debit once");at=now;phase=5;}
 else if(phase==5&&now-at>.40){Check(!Dialogue,"purchased room remains unobstructed after actual reveal",true);Check(view.Model.Snapshot.tutorial.storySeenMask==7,"hold does not consume queued story");Capture("purchase-room-hold");phase=6;}
 else if(phase==6&&now-at>1.1){Check(Dialogue,"queued story opens after presentation hold");Check(view.Model.Snapshot.tutorial.storySeenMask==7,"story unseen until explicit dismissal");Capture("queued-story");view.QaClick("tutorial-next");Check(view.Model.Snapshot.tutorial.storySeenMask==15,"explicit story dismissal persists");view.QaClick("menu");view.QaClick("motion-toggle");view.QaClick("close-settings");Check(PixelUi.ReducedMotion,"calm fixture selected");Set(FinishFixture(),3);phase=7;}
 else if(phase==7&&warm>30){view.QaClick("buy-7");at=now;phase=8;}
 else if(phase==8&&now-at>.10){Check(!Dialogue,"calm installation has brief unobstructed hold",true);phase=9;}
 else if(phase==9&&now-at>.55){Check(Dialogue,"calm queued story opens without loss");view.QaClick("tutorial-next");view.QaClick("menu");view.QaClick("motion-toggle");view.QaClick("close-settings");var s=new PlayerState{cash=60};s.fragments[0]=20;s.tutorial.completed=true;Set(s,0);phase=10;}
 else if(phase==10&&warm>30){Check(UI.Q<Button>("buy-0").enabledInHierarchy&&UI.Q<Label>("fragment-count-0").text=="20/20","exact 360x640 ready BUY twenty of twenty");Capture("ready-20-of-20");var s=FinishFixture();s.cash=int.MaxValue;s.fragments[7]=int.MaxValue;Set(s,3);phase=11;}
 else if(phase==11&&warm>30){var l=UI.Q<Label>("cash-count");var m=l.MeasureTextSize(l.text,0,VisualElement.MeasureMode.Undefined,0,VisualElement.MeasureMode.Undefined);Check(m.x<=l.contentRect.width+1,"maximum legacy balance/current final cost fits "+l.text);Capture("large-cash-current-cost");var s=new PlayerState{cash=int.MaxValue,freeSpins=0};for(int i=0;i<5;i++)s.purchased[i]=true;s.fragments[5]=int.MaxValue;s.tutorial.completed=true;s.tutorial.storySeenMask=7;Set(s,2);s=view.Model.Snapshot;s.quests[5].cashPrice=Economy.LegacyUpgrades[5].CashPrice;s.quests[5].fragmentGoal=Economy.LegacyUpgrades[5].FragmentGoal;Set(s,2);phase=111;}
 else if(phase==111&&warm>30){var l=UI.Q<Label>("cash-count");var m=l.MeasureTextSize(l.text,0,VisualElement.MeasureMode.Undefined,0,VisualElement.MeasureMode.Undefined);Check(view.Model.Definition(5).CashPrice==110,"largest permitted old-curve price preserved");Check(m.x<=l.contentRect.width+1,"maximum legacy cash/cost fits text="+l.text+" needs="+m.x+" has="+l.contentRect.width);Capture("legacy-max-cash-cost");Set(new PlayerState(),0);phase=12;}
 else if(phase==12&&warm>30){Check(Dialogue,"introduction visible");Check(UI.Q<Label>("dialogue-text").resolvedStyle.fontSize==13,"actual dialogue body thirteen pixels");Capture("dialogue-type");view.QaClick("menu");warm=0;phase=13;}
 else if(phase==13&&warm>30){var help=UI.Q<Label>("menu-help");Check(help.resolvedStyle.fontSize==14&&help.resolvedStyle.unityFontStyleAndWeight==FontStyle.Normal,"actual menu help regular fourteen pixels");Capture("menu-type");report.AppendLine("RESULT PASS; real Editor offscreen render; prepared fixtures and synthetic callbacks; no physical/OS input");Finish();}
 }catch(Exception e){report.AppendLine("FAIL "+e);Debug.LogException(e);Finish();}}
 static void Finish(){SessionState.SetBool(Key,false);File.WriteAllText(Path.Combine(Root,"Evidence","review-fixes-v06-"+Tag+"-checks.txt"),report.ToString());if(target!=null){view.GetComponent<UIDocument>().panelSettings.targetTexture=null;target.Release();UnityEngine.Object.Destroy(target);target=null;}EditorApplication.ExitPlaymode();}
 }
}